import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom'; // React Router의 useNavigate 훅 사용

function App() {
  const navigate = useNavigate(); // useNavigate 훅으로 네비게이션 기능 사용

  // 기본값을 설정하되, 이후 값이 변경되면 그 값으로 업데이트
  const [personality, setPersonality] = useState('T');
  const [gender, setGender] = useState('M');
  const [message, setMessage] = useState('');

  // 설정을 저장하는 함수
  const saveSettings = async () => {
    console.log('saveSettings 함수 호출됨');
    console.log('Personality:', personality);
    console.log('Gender:', gender);

    // personality 또는 gender가 빈 문자열이면 오류 메시지 출력
    if (!personality || !gender) {
      setMessage('모든 필드를 선택해주세요');
      return;
    }

    try {
      const response = await fetch('http://localhost:8000/settings/settings', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          personality: personality,  // 'T' 또는 'F' 값
          gender: gender,            // 'M' 또는 'W' 값
        }),
      });

      console.log('서버 응답:', response);

      if (!response.ok) {
        throw new Error('설정 업데이트 오류');
      }

      const data = await response.json();
      console.log('서버 응답 데이터:', data);
      setMessage(data.message || '설정이 성공적으로 업데이트되었습니다');

      // 여기서 로그 추가
      console.log('Navigating to /chat...');
      navigate("/chat");  // 페이지 이동 시도

      // 만약 navigate가 동작하지 않으면, 이 방법으로 이동할 수 있습니다.
      window.location.href = "/chat";  // 강제로 리다이렉트

    } catch (error) {
      console.error('오류 발생:', error);
      setMessage('설정 업데이트 오류: ' + error.message);
    }
  };

  return (
    <div>
      <h1>Chatbot Settings</h1>
      <div>
        <label>
          Personality:
          <select value={personality} onChange={(e) => setPersonality(e.target.value)}>
            <option value="T">Realistic</option>
            <option value="F">Emotional</option>
          </select>
        </label>
      </div>
      <div>
        <label>
          Gender:
          <select value={gender} onChange={(e) => setGender(e.target.value)}>
            <option value="M">Male</option>
            <option value="W">Female</option>
          </select>
        </label>
      </div>
      <button onClick={saveSettings}>Save Settings</button>

      <div>
        {message && <p>{message}</p>}
      </div>
    </div>
  );
}

export default App;
